periods.description:
@@preprocessing
<%_ {
const data=getMessageVar('stat_data',{defaults:{}}),world=_.get(data,'世界',{}),characters=_.get(data,'角色',{}),tasks=_.get(data,'任務',{});
const floor=Number(_.get(world,'當前樓層',1))||1,place=`${_.get(world,'當前區域','')} ${_.get(world,'詳細地點','')}`,time=`${_.get(world,'日期','')} ${_.get(world,'時間','')}`;
const sceneIds=_.get(world,'當前場景角色ID',[])||[],sceneNames=sceneIds.map(id=>characters[id]?.名稱).filter(Boolean);
const activeEvents=_.pickBy(_.get(world,'事件',{}),event=>!['已完成','已失敗','已取消','已失效'].includes(String(event?.狀態||'')));
const activeTasks=_.pickBy(tasks,task=>['候選','可接取','進行中'].includes(String(task?.狀態||'')));
const candidates=[];
for(const [id,event] of Object.entries(activeEvents)){
 const correctFloor=!event?.樓層||Number(event.樓層)===floor;
 const correctPlace=!event?.地點||place.includes(String(event.地點));
 const participants=event?.參與角色ID||[];
 const involved=!participants.length||participants.some(x=>sceneIds.includes(x));
 if(correctFloor&&correctPlace&&involved)candidates.push({ID:id,名稱:event.名稱||id,狀態:event.狀態,階段:event.階段,參與角色ID:participants});
}
_%>
<SAO_EVENT_ROUTER version="5.1.1">
目前時間：<%- time %>｜樓層：<%- floor %>｜地點：<%- place %>
在場角色：<%- JSON.stringify(sceneNames) %>
可推進事件：<%- JSON.stringify(candidates) %>
活動任務：<%- JSON.stringify(activeTasks) %>
規則：
1. `/世界/事件/<事件ID>`是事件唯一權威位置；事件內旗標包含在該事件的`旗標`子物件，不建立頂層旗標。
2. 靜態事件條目只是候選種子。必須同時滿足樓層、地點、時間、人物與前置才可建立或推進。
3. 原作角色首次實際登場或事件直接涉及時，以固定角色ID建立`/角色/<角色ID>`；只建立基礎敘事資料，戰鬥、交易、服務模組按需加入。
4. 組織唯一寫入`/世界/組織/<組織ID>`；未成立的候選組織不得提前擁有正式權限。
5. 事件造成的Col、HP、物品、經驗、隊伍、好感數值或時間變化，提交對應UnifiedAction，不直接更新結果。
6. 每輪最多推進一個主要事件；沒有合法候選時不強行生成重大事件。
</SAO_EVENT_ROUTER>
<%_ } _%>
